"""Behavior checks with generated bytecode; no copyrighted game fixtures."""
import struct
import sys
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'tools'))
from build_font_settings import (Builder, Script, SIZES, apply_function, draw_function,
                                click_function, init_function, pause_selector_function,
                                patch_console_bounded, hash32)
from check_font_settings import check_vm


def synthetic_dialogue(height, width=560, y=356):
    code = Builder().op('line', 240)
    for value in [height, width, y, 180, 123]:
        code.integer(value)
    raw = code.syscall(0x403960F8, 5).ret().finish()
    return (struct.pack('<16sIII', b'MajiroObjV1.000\0', 0, 1, 1)
            + struct.pack('<II', 0x1234, 0) + struct.pack('<I', len(raw)) + raw)


class FontSettingsTests(unittest.TestCase):
    def test_pause_menu_all_choices_and_current_value(self):
        hashes = {name: hash32('$cdx_font_' + name + '@NARCI_PAUSE')
                  for name in ['apply', 'selector']}
        functions = {hashes['apply']: apply_function(),
                     hashes['selector']: pause_selector_function(hashes['apply'])}
        check_vm(functions, hashes)

    def test_config_menu_all_choices_and_control_bounds(self):
        hashes = {name: hash32('$cdx_font_' + name + '@NARCI_CONFIG')
                  for name in ['apply', 'draw', 'click', 'noop', 'init']}
        functions = {hashes['apply']: apply_function(), hashes['draw']: draw_function(),
                     hashes['click']: click_function(hashes['apply'], hashes['draw']),
                     hashes['noop']: Builder().prologue(5).ret().finish(),
                     hashes['init']: init_function(hashes['apply'], hashes['draw'],
                                                  hashes['click'], hashes['noop'])}
        check_vm(functions, hashes)

    def test_narrow_narration_expands_without_moving_or_other_bytecode_changes(self):
        before_blob = synthetic_dialogue(60)
        after_blob, changes = patch_console_bounded(before_blob)
        before, after = Script(before_blob), Script(after_blob)
        difference = [(a, b) for a, b in zip(before.ins, after.ins) if a.raw != b.raw]
        self.assertEqual(len(difference), 1)
        self.assertEqual(difference[0][0].fields, {'i': 60})
        self.assertEqual(difference[0][1].fields, {'i': 220})
        self.assertEqual(before.functions, after.functions)
        self.assertEqual(len(before.code), len(after.code))
        self.assertEqual(changes[0]['bottom'], 576)
        for size in SIZES:
            self.assertLessEqual(size + 3 * (size + 4), 220)
        self.assertEqual(after.finish(), after_blob)

    def test_other_rectangles_are_not_matched_as_narrow_narration(self):
        for height, width, y in [(150, 560, 356), (60, 560, 100), (60, 300, 356)]:
            original = synthetic_dialogue(height, width, y)
            result, changes = patch_console_bounded(original)
            self.assertEqual(original, result)
            self.assertEqual(changes, [])


if __name__ == '__main__':
    unittest.main()
